<script setup lang="ts">const { login } = useAuth(); const form = reactive({ username: '', password: '' }); const error = ref(''); const submit = async () => { error.value = ''; try { await login(form.username, form.password); await navigateTo('/') } catch (e: any) { error.value = e?.data?.message || 'Unable to log in.' } }</script>
<template><section class="stack form"><h1>Log in</h1><form class="stack" @submit.prevent="submit"><label class="field">Username or email<input v-model="form.username" required /></label><label class="field">Password<input v-model="form.password" type="password" required /></label><p v-if="error">{{ error }}</p><button class="btn" type="submit">Log in</button></form><NuxtLink to="/register">Create an account</NuxtLink></section></template>
